(* Lean: angles128 *)
let angles128 = new_definition
 (mk_eq(mk_var("angles128",`:angle_enc list`),
        mk_list(Array.to_list angle128_tm,`:angle_enc`)));;

(* Lean: angle128_k_checked, k = 0..127 *)
let ANGLE128_CHECKED =
  Array.map (fun tm -> AE_CHECK_RULE (mk_comb(`ae_check`,tm))) angle128_tm;;

let AD128_ALL_CHECKED = prove
 (`ALL ae_check angles128`,
  REWRITE_TAC[angles128; ALL] THEN REWRITE_TAC(Array.to_list ANGLE128_CHECKED));;

let AD128_LENGTH = prove
 (`LENGTH angles128 = 128`,
  REWRITE_TAC[angles128; LENGTH] THEN CONV_TAC NUM_REDUCE_CONV);;

(* the indexed family: enclosure k of the 128-grid is checked *)
let ANGLES128_CHECKED = prove
 (`forall k. k < 128 ==> ae_check (EL k angles128)`,
  REPEAT STRIP_TAC THEN MP_TAC AD128_ALL_CHECKED THEN
  REWRITE_TAC[GSYM ALL_MEM] THEN DISCH_THEN MATCH_MP_TAC THEN
  MATCH_MP_TAC MEM_EL THEN ASM_REWRITE_TAC[AD128_LENGTH]);;

let AD128_EL = prove
 (list_mk_conj(map (fun k -> mk_eq(mk_comb(mk_comb(`EL:num->angle_enc list->angle_enc`,
     mk_small_numeral k),`angles128`), angle128_tm.(k))) (0--127)),
  REWRITE_TAC[angles128] THEN CONV_TAC(ONCE_DEPTH_CONV EL_CONV) THEN REWRITE_TAC[]);;

(* Lean: angles128_cover *)
let ANGLES128_COVER = prove
 (`covers_interval (&0) (&1) angles128`,
  REWRITE_TAC[angles128] THEN
  CONV_TAC(REWRITE_CONV[covers_interval; ae_lower; ae_upper] THENC
           REAL_RAT_REDUCE_CONV THENC REWRITE_CONV[]));;
